const next=[...new Set(cur.filter(x=>x!=="tomas").concat("paula"))];
const u=await tools.issue_write({owner:"octo",repo:"trailmap",method:"update",issue_number:n,assignees:next});
out.push({n,cur,next,res:(u.assignees||[]).map(a=>a.login)||u});}
